	const events: string[] = [];
	session.subscribe((event) => {
		if (event.type === "agent_settled") events.push(event.type);
	});

	await (session as any)._emitAgentSettled();

	expect(events).toEqual(["agent_settled"]);
	expect(command.handler).not.toHaveBeenCalled();
});

